{
  "name": "critical",
  "version": "9.0.0",
  "description": "Extract & inline critical-path CSS — two engines, automatic routing, agent-native.",
  "keywords": [
    "above-the-fold",
    "critical",
    "css",
    "inline",
    "lcp",
    "mcp",
    "performance"
  ],
  "license": "Apache-2.0",
  "author": "Addy Osmani",
  "repository": "addyosmani/critical",
  "bin": {
    "critical": "./cli.js"
  },
  "files": [
    "cli.js",
    "src"
  ],
  "type": "module",
  "types": "./src/index.d.ts",
  "exports": {
    ".": {
      "types": "./src/index.d.ts",
      "default": "./src/index.js"
    },
    "./mcp": {
      "types": "./src/mcp.d.ts",
      "default": "./src/mcp.js"
    }
  },
  "scripts": {
    "test": "node --test",
    "test:coverage": "node --test --experimental-test-coverage",
    "check": "vp check",
    "prepare": "vp config",
    "bench": "node bench/vs-beasties.mjs",
    "demo": "node cli.js ./fixtures --explain"
  },
  "dependencies": {
    "css-tree": "^3.1.0",
    "lightningcss": "^1.30.0",
    "linkedom": "^0.18.6"
  },
  "devDependencies": {
    "@modelcontextprotocol/sdk": "^1.0.0",
    "@vitest/coverage-v8": "catalog:",
    "beasties": "^0.3.0",
    "playwright": "^1.50.0",
    "vite": "catalog:",
    "vite-plus": "catalog:",
    "vitest": "catalog:"
  },
  "peerDependencies": {
    "@modelcontextprotocol/sdk": "^1.0.0",
    "playwright": "^1.50.0"
  },
  "peerDependenciesMeta": {
    "playwright": {
      "optional": true
    },
    "@modelcontextprotocol/sdk": {
      "optional": true
    }
  },
  "engines": {
    "node": ">=22.13.0"
  },
  "packageManager": "pnpm@11.5.0"
}

import { defineConfig } from "vite-plus";

export default defineConfig({
  staged: {
    "*": "vp check --fix",
  },
  fmt: {
    ignorePatterns: ["fixtures/**"],
  },
  lint: {},
  // Tests run on the platform runner (`node --test`), in keeping with v9's built-ins-first
  // philosophy; vite-plus stays for what it's great at — formatting and linting.
});

// @ts-check
import { defineConfig } from 'astro/config';
import react from '@astrojs/react';
import sitemap from '@astrojs/sitemap';
import tailwindcss from '@tailwindcss/vite';

// https://astro.build
export default defineConfig({
  site: 'https://clarity.addy.ie',
  trailingSlash: 'always',
  integrations: [
    react(),
    sitemap({
      filter: (page) => page !== 'https://clarity.addy.ie/example/',
    }),
  ],
  vite: { plugins: [tailwindcss()] },
  build: { inlineStylesheets: 'auto' },
  devToolbar: { enabled: false },
});

