{
  "name": "webpack-lighthouse-plugin",
  "version": "1.0.8",
  "description": "A Lighthouse plugin for Webpack",
  "main": "src/webpack-lighthouse-plugin.js",
  "scripts": {
    "demo": "cd test && webpack",
    "lint": "eslint src/webpack-shell-plugin.js",
    "clean": "rm -rf test/*.json test/*.html test/*.log"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/addyosmani/webpack-lighthouse-plugin.git"
  },
  "keywords": [
    "progressive web apps",
    "lighthouse",
    "performance",
    "auditing",
    "time to interactive",
    "tti",
    "first meaningful paint",
    "performance metrics",
    "performance audits"
  ],
  "author": "Addy Osmani",
  "license": "Apache-2.0",
  "bugs": {
    "url": "https://github.com/addyosmani/webpack-lighthouse-plugin/issues"
  },
  "homepage": "https://github.com/addyosmani/webpack-lighthouse-plugin#readme",
  "devDependencies": {
    "eslint": "^7.27.0",
    "eslint-config-google": "^0.14.0",
    "webpack": "^5.38.1",
    "webpack-cli": "^4.7.0"
  },
  "dependencies": {
    "lighthouse": "^8.0.0",
    "lighthouse-logger": "^1.2.0"
  }
}

{
  "extends": "google",
  "env": {
    "node": true
  },
  "rules": {
    "max-len": [2, 100, {
      "ignoreComments": true,
      "ignoreUrls": true,
      "tabWidth": 2
    }],
    "no-implicit-coercion": [2, {
      "boolean": false,
      "number": true,
      "string": true
    }],
    "no-unused-expressions": [2, {
      "allowShortCircuit": true,
      "allowTernary": false
    }],
    "no-unused-vars": [2, {
      "vars": "all",
      "args": "after-used",
      "argsIgnorePattern": "(^reject$|^_$)",
      "varsIgnorePattern": "(^_$)"
    }],
    "quotes": [2, "single"],
    "require-jsdoc": 0,
    "valid-jsdoc": 0,
    "comma-dangle": 0,
    "prefer-const": 2,
    "strict": [2, "global"]
  },
  "parserOptions": {
    "ecmaVersion": 6,
    "ecmaFeatures": {
      "globalReturn": true,
      "jsx": false,
      "experimentalObjectRestSpread": false
    },
    "sourceType": "script"
  }
}

